package br.uninter.baozistore.controller; import br.uninter.baozistore.model.*; import br.uninter.baozistore.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/clientes") public class ClienteController{ private final ClienteRepository r; public ClienteController(ClienteRepository r){this.r=r;} @PostMapping public Cliente salvar(@RequestBody Cliente c){return r.save(c);} @GetMapping public List<Cliente> listar(){return r.findAll();} @GetMapping("/{id}") public Cliente buscar(@PathVariable Long id){return r.findById(id).orElse(null);} @DeleteMapping("/{id}") public void excluir(@PathVariable Long id){r.deleteById(id);} }